                const useExtraColSpan = requireNewCol(column);

                const getAriaSort = () => {
                  if (!column.canSort || !column.isSorted) { return undefined };
                  return column.isSortedDesc ? 'descending' : 'ascending';
                };

                const getSortIconLabel = () => {
