            label={cancelLabel}
            {...cancelActionProps}
            onPress={mergeCallbacks([cancelActionProps.onPress, handleCancel])}
          />
          <Dialog.SubmitAction
            //autoFocus // Focus "confirm" by default?
            label={actionLabel}
            {...confirmActionProps}
            onPress={mergeCallbacks([cancelActionProps.onPress, handleConfirm])}
          />
        </>
