      trigger = () => null,
      allowUserClose = true,
      modalRef,
      providerProps,
      renderMethod = 'portal',
      ...propsRest
    } = props;

    return (
      <ModalProvider
        activeDefault={activeDefault}
        allowUserClose={allowUserClose}
        shouldCloseOnBackdropClick={display !== 'full-screen'}
